  public function envioEmail($object_id,$user_destino,$user_firma,$encabezado_cuerpo="")
  {      
    if(trim($encabezado_cuerpo) == "")
    {
      $encabezado_cuerpo = "Este es un mensaje para informarle que se radicado una PQR:";
    }
        
    $objeto_mail = PqrPeer::retrieveByPK($object_id);
    $usuario_destino = UsuarioPeer::retrieveByPK($user_destino);
    $usuario_firma = UsuarioPeer::retrieveByPK($user_firma);
        
    $cuerpo = '
    <html>
    <head>
    <title></title>
    </head>
    <body>
    <div id="cotenedor">
    <br>'.$encabezado_cuerpo.'
    <br>
    <br>
    <b>Prioridad:</b> '.$objeto_mail->getPrioridadPqr().'<br>
    <b>Categoria:</b> '.$objeto_mail->getCategoriaPqr().'<br>
    <b>Descripcion:</b> '.$objeto_mail->getObjeto().'<br>
    <b>Remitente:</b> '.$usuario_firma->getNombre().' '.$usuario_firma->getApellido().'<br>
    <b>Fecha Radicacion:</b> '.$objeto_mail->getFechaCreacion().' <br>                
    <br>
    </div>
    </body></html>';
    $cabeceras = "Content-type: text/html\r\n";
    //*********************************************************************************************************************
    $baseMail = new BaseMailSimad();
    $baseMail->SetSubject('CAD : Apoyo al usuario');
    $baseMail->SetMsgHTML($cuerpo);
    $baseMail->SetAddAddress($usuario_destino->getEmail(), $usuario_destino->getEmail());    
    if($baseMail->InitSend() === true)
    {
       $baseMail->writetolog("Alerta enviada: " . $usuario_destino->getEmail() . " Enviado a: " . $usuario_destino->getEmail());
    }else{
       $baseMail->writetolog("Error al enviar alerta: " . $usuario_destino->getEmail() . " Cuenta correo: " . $usuario_destino->getEmail());
    }
    //***********************************************************************************************************************
  }
  
