    public function executeHistorial()
    {   
    	$pqr = PqrPeer::retrieveByPk($this->getRequestParameter('pqr_id'));
    	$this->pqrId = $pqr->getPqrId();
		$this->ser = $pqr;    			
		$c = new Criteria();
		$c->add(AsignacionPqrPeer::PQR_ID, $this->getRequestParameter('pqr_id'));				
		$c->addAnd(AsignacionPqrPeer::ESTADOASIGNACIONPQR_ID,1);
		
		$x = new Criteria();
		$x->add(AsignacionPqrPeer::PQR_ID, $this->getRequestParameter('pqr_id'));				
		$x->addAnd(AsignacionPqrPeer::ESTADOASIGNACIONPQR_ID,2);
		$resp = AsignacionPqrPeer::doSelect($x);
		$i = 0;
		$nomb = array();
        $this->asignacion_activa = "";	    
    	foreach ($resp as $result){            			
          $nomb[$i] = $result->getUsuario()->getNombre()." ".$result->getUsuario()->getApellido();
		  
		  if($result->getEstaAsignado())
		    $this->asignacion_activa = $i;
		    $i++;
		  }			              		         
		$this->nomb = $nomb;
				
		$this->parametros .= "&pqr_id=" . $this->getRequestParameter('pqr_id');		
        $pager = new sfPropelPager('AsignacionPqr', 10);
        $pager->setCriteria($c);        
        $pager->setPage($this->getRequestParameter('page', 1));
        $pager->init();
        $this->pager = $pager;                		  	   
    }
