		$a->add(AsignacionPqrPeer::PQR_ID,$this->getRequestParameter('pqr_id'));
		//$a->add(AsignacionPqrPeer::USUARIO_ID,$this->getUser()->getAttribute('usuario_id', '', 'subscriber'));
		$a->add(AsignacionPqrPeer::ESTADOASIGNACIONPQR_ID,2);
		$a->add(AsignacionPqrPeer::ESTA_ASIGNADO,1);				
		$resp = AsignacionPqrPeer::doSelectOne($a);
		
        $pqr = AsignacionPqrPeer::retrieveByPk($resp->getAsignacionpqrId());
		$pqr->setEstaAsignado(false);
		//$pqr->setEstadoasignacionpqrId(1);
		$pqr->save();
        /**********************************************************************************************************/
        /*********************************************************************************************************/         //codigo para usuario que asigno el pqr
		$userasigno   = new AsignacionPqr();                
        $userasigno->setEstadoasignacionpqrId(1);
        $userasigno->setPqrId($this->getRequestParameter('pqr_id'));
        $userasigno->setUsuarioId($this->getUser()->getAttribute('usuario_id', '', 'subscriber'));
        $userasigno->setFechaCreacion(date("Y-m-d G:i:s"));
        $userasigno->setEstaAsignado(false);
        $userasigno->save();
		/*********************************************************************************************************/
		/**********************************************************************************************************/
        //codigo para usuario asignado a la pqr
		$userasignado   = new AsignacionPqr();                
        $userasignado->setEstadoasignacionpqrId(2);
        $userasignado->setPqrId($this->getRequestParameter('pqr_id'));
        $userasignado->setUsuarioId($this->getRequestParameter('usuario_id'));
        $userasignado->setFechaCreacion(date("Y-m-d  G:i:s"));
        $userasignado->setEstaAsignado(true);
        $userasignado->save();
        /********************************************************************************************************/       
        /********************************************************************************************************/
        //guardar en la BD el nuevo estado de la PQR
        $pqr = PqrPeer::retrieveByPk($this->getRequestParameter('pqr_id'));
        $pqr->setEstadopqrId($this->getRequestParameter('estadopqr_id'));
        $pqr->save();
        /*********************************************************************************************************/
        		
		return $this->redirect($this->getRequest()->getScriptName().'/pqr/show?pqr_id='.$this->getRequestParameter('pqr_id'));
	}
    
		
	public function asignarUserPqr($id_pqr, $reg)
    {
    	/*********************************************************************************************************/         //codigo para usuario que asigno la pqr
		$userasigno  = new AsignacionPqr();		
		$userasigno->setEstadoasignacionpqrId(1);
		$userasigno->setPqrId($id_pqr);
		$userasigno->setUsuarioId($this->getUser()->getAttribute('usuario_id', '', 'subscriber'));
		$userasigno->setFechaCreacion(date("Y-m-d G:i:s"));
		$userasigno->setEstaAsignado(false);
		$userasigno->save();
		/**********************************************************************************************************/
		
    	/**********************************************************************************************************/
        //codigo para usuario al que se le asigna la pqr
		$userasignado   = new AsignacionPqr();                
        $userasignado->setEstadoasignacionpqrId(2);
        $userasignado->setPqrId($id_pqr);
        $userasignado->setUsuarioId($this->getReceptorId());
        $userasignado->setFechaCreacion(date("Y-m-d G:i:s"));
        $userasignado->setEstaAsignado(true);
        $userasignado->save();
        /*********************************************************************************************************/        		
    }
    
    public function getReceptorId()
    {
    	/****************************************************************************************************/
    	$usuariologueado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    	try{
	        $c = new Criteria();                
	        $c->add(FacturaReceptorPeer::FACTURAPROCESO_ID,7);
	        $c->add(FacturaReceptorPeer::REGIONAL_ID, $this->getRegional($usuariologueado));
	        $resp = FacturaReceptorPeer::doSelectOne($c);
	        if($resp){
	        	return $resp->getUsuarioId();
	        }else{
	        	return null;
	        }
    	}catch (Exception $ex){
    		return null;
    	}
    }
    
    public function getNewConsecutivo()
	{
		$cons = ParametroPeer::retrieveByPk(8);
		$regId = $cons->getValorNumerico();
		if($regId > 0){
			$cons->setValorNumerico($regId+1);
			$cons->save();
		}
		return $regId;		
	}
		
    public function getRegional($userId)
	{
		$user = UsuarioPeer::retrieveByPk($userId);
		$regId = $user->getRegionalId();
		return $regId;		
	}
}